// Package nuts provides shared NATS connection-lifecycle helpers for Entire
// services: a rotation-aware mTLS [Connect] with the org-standard resiliency
// options, a [Drain] that waits for a connection to flush and close on graceful
// shutdown, an [IsShutdownFetchErr] classifier so pull-consumer loops can treat
// a drain/close during shutdown as a clean exit rather than an error, and a
// [ShutdownGroup] that cancels background loops, joins them, and only then
// drains the connections — the ordering that keeps a Drain from racing an
// in-flight Fetch (COR-923).
//
// This root package is the connection-lifecycle core extracted from
// entire-core (entiredb), entire-api, and mirror-pipeline, which had each
// grown their own copy of this plumbing (COR-925). It depends only on nats.go.
//
// The subpackages carry the consumer-side layers those services shared
// (COR-929) — [natsmsg] (trace-context propagation over message headers, the
// KeepInProgress AckWait heartbeat, and the natsmsgtest.FakeMsg test double),
// [jsconsumer] (the durable JetStream pull-consumer scaffold), and [backoff]
// (the flat NakWithDelay redelivery policy with Term-on-final-delivery,
// COR-762). natsmsg and jsconsumer additionally depend on the OpenTelemetry
// API, and all three on nats.go's jetstream package; importing only the root
// package links none of that.
//
// [natsmsg]: https://pkg.go.dev/github.com/entireio/go-nuts/natsmsg
// [jsconsumer]: https://pkg.go.dev/github.com/entireio/go-nuts/jsconsumer
// [backoff]: https://pkg.go.dev/github.com/entireio/go-nuts/backoff
package nuts

package nuts

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"time"

	"github.com/nats-io/nats.go"
)

// Default connection tunables. DefaultDrainTimeout matches entire-core's tuned
// value (COR-923); nats.go's own default is 30s. It caps only the
// subscription-drain phase — see [Drain] for why it is not the whole budget.
const (
	DefaultDrainTimeout  = 5 * time.Second
	DefaultReconnectWait = 2 * time.Second
)

// natsPublishDrainTimeout is the fixed publish-flush budget nats.go spends
// after the subscription-drain phase before a drained connection reaches CLOSED
// (the hardcoded FlushTimeout in (*nats.Conn).drainConnection). A total
// time-to-CLOSED backstop must exceed a connection's nats.DrainTimeout by at
// least this much, plus a little slack, to avoid firing mid-flush.
const natsPublishDrainTimeout = 5 * time.Second

// Environment variables that carry the org-wide mTLS client identity. The same
// triple is consumed by every Entire service that dials NATS.
const (
	envTLSCert = "ENTIRE_INTERNAL_TLS_CERT_FILE"
	envTLSKey  = "ENTIRE_INTERNAL_TLS_KEY_FILE"
	envTLSCA   = "ENTIRE_INTERNAL_TLS_CA_FILE"
)

// config holds the resolved connection settings. Callers mutate it through
// [Option] values.
type config struct {
	name                 string
	logger               *slog.Logger
	tlsConfig            *tls.Config
	tlsFromEnv           bool
	drainTimeout         time.Duration
	reconnectWait        time.Duration
	maxReconnects        int
	retryOnFailedConnect bool
	extra                []nats.Option
}

// Option configures a [Connect] call.
type Option func(*config)

// WithName sets the NATS connection name (nats.Name), which labels the client
// in server monitoring and in the logs.
func WithName(name string) Option { return func(c *config) { c.name = name } }

// WithLogger sets the logger used for connection lifecycle events. Defaults to
// [slog.Default]. Context-aware log methods are used, so a handler that reads
// trace context from the context still works.
func WithLogger(l *slog.Logger) Option { return func(c *config) { c.logger = l } }

// WithTLSConfig supplies an explicit *tls.Config and disables the default
// env-var mTLS lookup. Pass this (or [WithoutTLS]) when the standard
// ENTIRE_INTERNAL_TLS_* identity does not apply.
func WithTLSConfig(t *tls.Config) Option {
	return func(c *config) {
		c.tlsConfig = t
		c.tlsFromEnv = false
	}
}

// WithoutTLS disables TLS entirely (plaintext). Intended for local development
// and tests against an embedded server; production dials always use mTLS.
func WithoutTLS() Option {
	return func(c *config) {
		c.tlsConfig = nil
		c.tlsFromEnv = false
	}
}

// WithDrainTimeout overrides [DefaultDrainTimeout].
func WithDrainTimeout(d time.Duration) Option { return func(c *config) { c.drainTimeout = d } }

// WithReconnectWait overrides [DefaultReconnectWait].
func WithReconnectWait(d time.Duration) Option { return func(c *config) { c.reconnectWait = d } }

// WithRetryOnFailedConnect keeps [Connect] from returning an error when the
// initial dial fails: nats.go instead returns a connection in RECONNECTING
// state and retries in the background (buffering publishes). It is off by
// default so a misconfigured connection (bad URL, wrong TLS material) fails
// fast at startup — crash-looping the pod so a bad rollout is visible — rather
// than silently accepting work it cannot deliver. Enable it only for
// optional/secondary connections a service is designed to run without.
func WithRetryOnFailedConnect() Option {
	return func(c *config) { c.retryOnFailedConnect = true }
}

// WithNATSOptions appends raw nats.Option values, applied after nuts's
// defaults so a caller can override any of them. An escape hatch for options
// nuts does not model.
func WithNATSOptions(opts ...nats.Option) Option {
	return func(c *config) { c.extra = append(c.extra, opts...) }
}

// Connect opens a NATS connection with the org-standard resiliency posture:
// rotation-aware mTLS (from the ENTIRE_INTERNAL_TLS_* env vars unless
// overridden), reconnect-forever (long-lived services must outlive arbitrary
// NATS outages rather than permanently CLOSE after the client default of 60
// attempts), a bounded drain timeout, and lifecycle handlers that log at the
// right level — notably routing the nil-error DisconnectErr that nats.go fires
// on an explicit Close to INFO, so a clean shutdown does not look like a fault.
//
// The initial dial is fail-fast: if the first connect does not succeed Connect
// returns an error, so a misconfigured service crash-loops visibly rather than
// booting into a broken state. Reconnect-forever applies only once a connection
// has been established. Pass [WithRetryOnFailedConnect] to opt into background
// retry of the initial dial instead.
//
// The returned connection should be torn down with [Drain] (or via a
// [ShutdownGroup]) on graceful shutdown, not nc.Close, so in-flight work
// finishes and pull-consumer fetch loops exit cleanly.
func Connect(ctx context.Context, url string, opts ...Option) (*nats.Conn, error) {
	if url == "" {
		return nil, errors.New("nuts: nats url is empty")
	}
	cfg := config{
		logger:        slog.Default(),
		tlsFromEnv:    true,
		drainTimeout:  DefaultDrainTimeout,
		reconnectWait: DefaultReconnectWait,
		maxReconnects: -1,
	}
	for _, o := range opts {
		o(&cfg)
	}
	if cfg.logger == nil {
		cfg.logger = slog.Default()
	}

	var tlsConf *tls.Config
	switch {
	case cfg.tlsConfig != nil:
		tlsConf = cfg.tlsConfig
	case cfg.tlsFromEnv:
		var err error
		if tlsConf, err = tlsConfigFromEnv(); err != nil {
			return nil, err
		}
	}

	// The lifecycle handlers below outlive the Connect call — they fire on
	// disconnects and reconnects for the whole life of the connection, long
	// after a startup- or request-scoped ctx is cancelled. Log through a
	// cancellation-detached copy so a context-aware slog handler still sees the
	// trace values but never drops a mid-life event because ctx is already done.
	logCtx := context.WithoutCancel(ctx)
	connAttr := slog.String("conn", cfg.name)

	natsOpts := []nats.Option{
		nats.DrainTimeout(cfg.drainTimeout),
		nats.RetryOnFailedConnect(cfg.retryOnFailedConnect),
		nats.MaxReconnects(cfg.maxReconnects),
		nats.ReconnectWait(cfg.reconnectWait),
		nats.DisconnectErrHandler(func(_ *nats.Conn, err error) {
			// nats.go fires this with err==nil when the caller calls Close()
			// explicitly (see nats.Options.DisconnectedErrCB). Logging that at
			// ERROR makes clean shutdowns look like failures, so route the
			// explicit-close case to INFO.
			if err == nil {
				cfg.logger.InfoContext(logCtx, "nuts: NATS disconnected", connAttr)
				return
			}
			cfg.logger.ErrorContext(logCtx, "nuts: NATS disconnected", connAttr, slog.Any("error", err))
		}),
		nats.ClosedHandler(func(_ *nats.Conn) {
			cfg.logger.InfoContext(logCtx, "nuts: NATS connection closed", connAttr)
		}),
		nats.ReconnectHandler(func(_ *nats.Conn) {
			cfg.logger.InfoContext(logCtx, "nuts: NATS reconnected", connAttr)
		}),
		nats.ReconnectErrHandler(func(_ *nats.Conn, err error) {
			cfg.logger.ErrorContext(logCtx, "nuts: NATS reconnect failed", connAttr, slog.Any("error", err))
		}),
	}
	if tlsConf != nil {
		natsOpts = append(natsOpts, nats.Secure(tlsConf))
	}
	if cfg.name != "" {
		natsOpts = append(natsOpts, nats.Name(cfg.name))
	}
	natsOpts = append(natsOpts, cfg.extra...)

	nc, err := nats.Connect(url, natsOpts...)
	if err != nil {
		return nil, fmt.Errorf("nuts: connect to NATS: %w", err)
	}
	// With RetryOnFailedConnect enabled, nats.Connect returns a nil error even
	// when the initial dial failed — the connection is in RECONNECTING and the
	// client is retrying in the background. Report that honestly instead of
	// claiming "connected".
	if status := nc.Status(); status != nats.CONNECTED {
		cfg.logger.WarnContext(ctx, "nuts: NATS not yet connected; retrying in background",
			connAttr, slog.String("url", url), slog.String("status", status.String()))
		return nc, nil
	}
	cfg.logger.InfoContext(ctx, "nuts: NATS connected", connAttr, slog.String("url", url))
	return nc, nil
}

// tlsConfigFromEnv builds the mTLS config from the ENTIRE_INTERNAL_TLS_* env
// vars, requiring all three to be set.
func tlsConfigFromEnv() (*tls.Config, error) {
	cert, key, ca := os.Getenv(envTLSCert), os.Getenv(envTLSKey), os.Getenv(envTLSCA)
	if cert == "" || key == "" || ca == "" {
		return nil, fmt.Errorf("nuts: %s, %s, %s all required for NATS mTLS", envTLSCert, envTLSKey, envTLSCA)
	}
	return TLSConfigFromFiles(cert, key, ca)
}

// TLSConfigFromFiles builds a fully rotation-aware mTLS *tls.Config from cert,
// key, and CA files on disk. Both sides of the trust are re-read from disk on
// every handshake: GetClientCertificate reloads the client keypair, and
// VerifyConnection rebuilds the root pool from the CA file and verifies the
// server against it. A cert-manager rotation of either the client identity or
// the trusted CA is therefore picked up on the next reconnect without a process
// restart. The files are read and parsed once here so a misconfiguration fails
// fast at construction time rather than on the first handshake.
//
// Because the roots must be resolved per handshake, verification is done in
// VerifyConnection (which also re-checks the server hostname) rather than via
// the static RootCAs field.
func TLSConfigFromFiles(certFile, keyFile, caFile string) (*tls.Config, error) {
	if _, err := tls.LoadX509KeyPair(certFile, keyFile); err != nil {
		return nil, fmt.Errorf("nuts: load tls keypair: %w", err)
	}
	if _, err := caPoolFromFile(caFile); err != nil {
		return nil, err
	}
	return &tls.Config{
		GetClientCertificate: func(*tls.CertificateRequestInfo) (*tls.Certificate, error) {
			cert, err := tls.LoadX509KeyPair(certFile, keyFile)
			if err != nil {
				return nil, fmt.Errorf("nuts: reload tls keypair: %w", err)
			}
			return &cert, nil
		},
		// Roots are resolved per handshake in VerifyConnection, so default
		// verification (which would pin a static RootCAs) is turned off and
		// replaced with an equivalent check against a freshly-read pool.
		InsecureSkipVerify: true, //nolint:gosec // server cert + hostname are verified against a freshly-read CA pool in VerifyConnection to stay rotation-aware
		VerifyConnection: func(cs tls.ConnectionState) error {
			roots, err := caPoolFromFile(caFile)
			if err != nil {
				return err
			}
			if len(cs.PeerCertificates) == 0 {
				return errors.New("nuts: server presented no certificate")
			}
			opts := x509.VerifyOptions{
				Roots:         roots,
				DNSName:       cs.ServerName,
				Intermediates: x509.NewCertPool(),
			}
			for _, cert := range cs.PeerCertificates[1:] {
				opts.Intermediates.AddCert(cert)
			}
			if _, err := cs.PeerCertificates[0].Verify(opts); err != nil {
				return fmt.Errorf("nuts: verify server certificate: %w", err)
			}
			return nil
		},
		MinVersion: tls.VersionTLS13,
	}, nil
}

// caPoolFromFile reads a PEM CA bundle from disk and returns it as a cert pool,
// erroring if the file cannot be read or contains no parseable certificates.
func caPoolFromFile(caFile string) (*x509.CertPool, error) {
	caBytes, err := os.ReadFile(caFile)
	if err != nil {
		return nil, fmt.Errorf("nuts: read ca: %w", err)
	}
	pool := x509.NewCertPool()
	if !pool.AppendCertsFromPEM(caBytes) {
		return nil, errors.New("nuts: ca PEM: no certs parsed")
	}
	return pool, nil
}

package nuts

import (
	"context"
	"errors"
	"log/slog"
	"time"

	"github.com/nats-io/nats.go"
)

// IsShutdownFetchErr reports whether a pull-consumer Fetch error is the benign
// result of the connection being drained/closed during shutdown rather than a
// real fault. It is only "clean" when ctx is already done — a mid-run
// connection loss (ctx still live) is a genuine error worth logging.
//
// Use it to gate the error log in a fetch loop:
//
//	msgs, err := sub.Fetch(1, nats.MaxWait(5*time.Second))
//	if err != nil {
//		if errors.Is(err, nats.ErrTimeout) || nuts.IsShutdownFetchErr(ctx, err) {
//			// benign: idle poll, or a drain/close during shutdown
//		}
//		...
//	}
func IsShutdownFetchErr(ctx context.Context, err error) bool {
	return ctx.Err() != nil &&
		(errors.Is(err, nats.ErrConnectionClosed) || errors.Is(err, nats.ErrConnectionDraining))
}

// Drain drains nc and waits (bounded by timeout) for it to flush pending
// acks/publishes and reach CLOSED. nats.go's Conn.Drain is asynchronous — it
// starts the drain on a background goroutine and returns immediately — so a
// bare Drain in a shutdown cleanup would let the process exit before the flush
// completes. This subscribes to the connection's CLOSED status event, starts
// the drain, and blocks until the connection closes or timeout elapses. name
// labels the connection in the logs so a wedged drain can be attributed, and
// diagnostics are written to logger (defaulting to [slog.Default] when nil).
//
// timeout is the TOTAL time-to-CLOSED backstop, not the subscription-drain
// budget. The connect-time nats.DrainTimeout option caps only the
// subscription-drain phase; nats.go then runs an unconditional 5s publish flush
// before closing, so the true time-to-CLOSED is up to that flush longer than
// nats.DrainTimeout. timeout must exceed the connection's nats.DrainTimeout by
// at least the publish-flush budget or it will fire mid-drain and drop pending
// acks — [ShutdownGroup] sizes it automatically. timeout bounds how long we
// block; it is not a guarantee the drain finished. Once the consumer loops have
// joined (see [ShutdownGroup]) there is nothing left to drain, so on a reachable
// server this returns in milliseconds; the backstop only bites when the server
// is unreachable.
//
// Unlike a raw nc.Drain, this does not touch the connection's ClosedHandler, so
// a handler installed by [Connect] or by the caller (via [WithNATSOptions]) is
// preserved, and concurrent Drain calls on the same connection do not clobber
// one another.
//
// Drain is a no-op on a nil or already-closed connection.
func Drain(ctx context.Context, nc *nats.Conn, name string, logger *slog.Logger, timeout time.Duration) {
	if logger == nil {
		logger = slog.Default()
	}
	if nc == nil || nc.IsClosed() {
		return
	}

	// Register for the CLOSED transition before starting the drain so it cannot
	// be missed, and via a status listener rather than SetClosedHandler so we
	// never displace a handler the connection already has.
	closed := nc.StatusChanged(nats.CLOSED)
	defer nc.RemoveStatusListener(closed)

	if err := nc.Drain(); err != nil {
		logger.WarnContext(ctx, "nuts: NATS drain failed; closing",
			slog.String("conn", name), slog.Any("error", err))
		nc.Close()
		return
	}

	select {
	case <-closed:
		logger.InfoContext(ctx, "nuts: NATS drained", slog.String("conn", name))
	case <-time.After(timeout):
		logger.WarnContext(ctx, "nuts: NATS drain timed out before close", slog.String("conn", name))
	}
}

package nuts

import (
	"context"
	"log/slog"
	"runtime/debug"
	"sync"
	"time"

	"github.com/nats-io/nats.go"
)

// DefaultJoinTimeout bounds how long [ShutdownGroup.Shutdown] waits for
// background loops to return before draining the connections anyway.
const DefaultJoinTimeout = 10 * time.Second

// ShutdownGroup coordinates graceful shutdown of a set of background
// pull-consumer loops and the NATS connections they use. It encodes the
// ordering that prevents rollout noise (COR-923): on Shutdown it cancels the
// loops' context, waits for them to return, and only THEN drains the
// connections — so a Drain never races an in-flight Fetch.
//
// Typical use in a service main:
//
//	g := nuts.NewShutdownGroup(ctx)
//	nc, _ := nuts.Connect(g.Context(), url, nuts.WithName("worker"))
//	g.AddConn("worker", nc)
//	g.Go(func(ctx context.Context) { consumer.Run(ctx) }) // returns on ctx.Done
//	<-ctx.Done() // SIGTERM/SIGINT
//	g.Shutdown()
type ShutdownGroup struct {
	ctx          context.Context
	cancel       context.CancelFunc
	logger       *slog.Logger
	joinTimeout  time.Duration
	drainTimeout time.Duration

	wg     sync.WaitGroup
	mu     sync.Mutex
	conns  []groupConn
	closed bool // set under mu once shutdown starts; gates Go registration
	once   sync.Once
}

type groupConn struct {
	name string
	nc   *nats.Conn
}

// GroupOption configures a [ShutdownGroup].
type GroupOption func(*ShutdownGroup)

// WithGroupLogger sets the logger for shutdown diagnostics. Defaults to
// [slog.Default].
func WithGroupLogger(l *slog.Logger) GroupOption { return func(g *ShutdownGroup) { g.logger = l } }

// WithJoinTimeout overrides [DefaultJoinTimeout] — the bound on waiting for
// background loops to return.
func WithJoinTimeout(d time.Duration) GroupOption {
	return func(g *ShutdownGroup) { g.joinTimeout = d }
}

// WithGroupDrainTimeout overrides the fallback subscription-drain budget
// ([DefaultDrainTimeout]) used when draining a registered connection that does
// not carry its own nats.DrainTimeout. A connection created with
// [WithDrainTimeout] is drained on its own budget regardless; the total
// time-to-CLOSED backstop adds publish-flush headroom on top (see [Drain]).
func WithGroupDrainTimeout(d time.Duration) GroupOption {
	return func(g *ShutdownGroup) { g.drainTimeout = d }
}

// NewShutdownGroup returns a group whose context derives from parent and is
// cancelled by [ShutdownGroup.Shutdown].
func NewShutdownGroup(parent context.Context, opts ...GroupOption) *ShutdownGroup {
	//nolint:gosec // cancel is retained in g.cancel and invoked by Shutdown (via shutdown), not leaked
	ctx, cancel := context.WithCancel(parent)
	g := &ShutdownGroup{
		ctx:          ctx,
		cancel:       cancel,
		logger:       slog.Default(),
		joinTimeout:  DefaultJoinTimeout,
		drainTimeout: DefaultDrainTimeout,
	}
	for _, o := range opts {
		o(g)
	}
	if g.logger == nil {
		g.logger = slog.Default()
	}
	return g
}

// Context returns the group's context, cancelled when Shutdown is called. Pass
// it to every background loop and to [Connect] so the loops exit before their
// connections are drained.
func (g *ShutdownGroup) Context() context.Context { return g.ctx }

// Go runs fn as a tracked background loop. fn MUST return when its context is
// cancelled; Shutdown blocks (bounded by the join timeout) until it does.
//
// A panic in fn is recovered and logged with a stack (at ERROR) rather than
// crashing the whole process, so one bad message in one loop does not take down
// every other loop on the pod. A return while the group context is still live
// is treated as a dead subsystem and logged at ERROR too — a tracked loop is
// expected to run until Shutdown cancels it.
//
// Registering a loop after Shutdown has begun is a no-op: the loop would not be
// joined before the connections drain, so it is refused and logged rather than
// started. Go is safe to call concurrently with Shutdown.
func (g *ShutdownGroup) Go(fn func(ctx context.Context)) {
	// Add under the same lock that Shutdown takes before it calls wg.Wait, so a
	// concurrent Go/Shutdown can never race Add against Wait (which panics), and
	// a loop registered after shutdown starts is refused rather than left
	// unjoined.
	g.mu.Lock()
	if g.closed {
		g.mu.Unlock()
		g.logger.WarnContext(g.ctx, "nuts: ShutdownGroup.Go called after shutdown; loop not started")
		return
	}
	g.wg.Add(1)
	g.mu.Unlock()

	go func() {
		defer g.wg.Done()
		defer func() {
			if r := recover(); r != nil {
				g.logger.ErrorContext(g.ctx, "nuts: background loop panicked",
					slog.Any("panic", r), slog.String("stack", string(debug.Stack())))
				return
			}
			// A clean return before the context is cancelled means the loop
			// stopped supervising its subsystem while it was still supposed to
			// be running — surface it instead of letting the pod look healthy.
			if g.ctx.Err() == nil {
				g.logger.ErrorContext(g.ctx, "nuts: background loop returned before shutdown")
			}
		}()
		fn(g.ctx)
	}()
}

// AddConn registers a connection to be drained after the loops have joined.
// Draining last — never before the fetch loops stop — is the ordering that
// keeps a Drain/Close from racing an in-flight Fetch (COR-923).
//
// Like [ShutdownGroup.Go], registering after Shutdown has begun is a no-op:
// the drain set is snapshotted when shutdown starts, so a connection added
// afterward (including during the join window) would never be drained. It is
// refused and logged rather than silently dropped — the caller then owns
// tearing it down. Uses the same lock as shutdown's snapshot, so a connection
// is either in the snapshot or explicitly refused, never lost to a race.
func (g *ShutdownGroup) AddConn(name string, nc *nats.Conn) {
	g.mu.Lock()
	if g.closed {
		g.mu.Unlock()
		g.logger.WarnContext(g.ctx, "nuts: ShutdownGroup.AddConn called after shutdown; connection not registered for drain",
			slog.String("conn", name))
		return
	}
	g.conns = append(g.conns, groupConn{name: name, nc: nc})
	g.mu.Unlock()
}

// Shutdown cancels the group context, waits (bounded by the join timeout) for
// every Go loop to return, then drains every registered connection. It is safe
// to call more than once; only the first call has an effect.
func (g *ShutdownGroup) Shutdown() {
	g.once.Do(g.shutdown)
}

func (g *ShutdownGroup) shutdown() {
	// Mark closed and snapshot the connections under the lock that Go also
	// takes. After this point no new loop can register (see Go), so the wg.Wait
	// below cannot race a concurrent Add.
	g.mu.Lock()
	g.closed = true
	conns := g.conns
	g.mu.Unlock()

	g.cancel()

	done := make(chan struct{})
	go func() {
		g.wg.Wait()
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(g.joinTimeout):
		g.logger.WarnContext(g.ctx, "nuts: background loops did not stop within join timeout; draining anyway",
			slog.Duration("join_timeout", g.joinTimeout))
	}

	// Drain the connections concurrently: they are independent, so the group's
	// worst-case shutdown is one drain backstop, not the sum across connections.
	var dwg sync.WaitGroup
	for _, c := range conns {
		dwg.Add(1)
		go func() {
			defer dwg.Done()
			Drain(g.ctx, c.nc, c.name, g.logger, g.drainBackstop(c.nc))
		}()
	}
	dwg.Wait()
}

// drainBackstop returns the total time-to-CLOSED budget for draining nc. It
// honors the connection's own configured nats.DrainTimeout (set via
// [WithDrainTimeout]) when present, falling back to the group's drain timeout,
// then adds headroom for the publish flush nats.go runs after the
// subscription-drain phase so the backstop does not fire mid-drain (see
// [Drain]).
func (g *ShutdownGroup) drainBackstop(nc *nats.Conn) time.Duration {
	subDrain := g.drainTimeout
	if nc != nil && nc.Opts.DrainTimeout > 0 {
		subDrain = nc.Opts.DrainTimeout
	}
	return subDrain + natsPublishDrainTimeout + time.Second
}

// Package jsconsumer is the durable JetStream pull-consumer scaffold shared by
// Entire's decode-and-dispatch consumers. Each of those used to hand-roll the
// same lifecycle: jetstream.New → CreateOrUpdateConsumer (durable, explicit
// ack, bounded ack-wait, bounded MaxDeliver, filter subject) → Consume → stop
// on context cancel; and the same per-message prologue: open a consumer span
// (re-parented across the NATS hop), decode the payload, and Term on a decode
// error.
//
// This package owns exactly that scaffold and nothing else. Each consumer
// keeps its OWN event type, business dispatch, metrics, and log lines — Start
// takes the consumer's message callback, and Process invokes the consumer's
// handle with the decoded event and the live span. The handler owns the
// message's terminal disposition (Ack/Nak/Term); Process never touches a
// message that decoded.
//
// Lifted from entire-api's internal/jsconsumer (COR-929), folding in the
// module's shutdown classification ([nuts.IsShutdownFetchErr] gates the
// consume-error log so a drain during rollout isn't reported as a fault,
// COR-923) and an optional [natsmsg.KeepInProgress] heartbeat for consumers
// whose handlers legitimately outrun AckWait.
package jsconsumer

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"sync"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/codes"
	"go.opentelemetry.io/otel/trace"

	"github.com/entireio/go-nuts"
	"github.com/entireio/go-nuts/natsmsg"
)

const (
	// DefaultAckWait is how long JetStream waits for an ack before redelivery
	// when Config.AckWait is zero — comfortably longer than an RPC round-trip
	// plus a DB upsert, short enough that a stuck message redelivers promptly.
	DefaultAckWait = 30 * time.Second
	// DefaultMaxDeliver caps redelivery before JetStream stops redelivering a
	// message when Config.MaxDeliver is zero.
	DefaultMaxDeliver = 8
)

// Config describes the durable consumer to create and how to trace/log it. The
// filter is given as either FilterSubject (single) or FilterSubjects (multi),
// mirroring jetstream.ConsumerConfig, so a migrated consumer preserves its
// existing on-server filter form exactly.
type Config struct {
	Stream         string        // JetStream stream to bind (must already exist)
	Durable        string        // durable consumer name, stable across restarts
	FilterSubject  string        // set this OR FilterSubjects
	FilterSubjects []string      // set this OR FilterSubject
	AckWait        time.Duration // 0 → DefaultAckWait (see EffectiveAckWait)
	MaxDeliver     int           // 0 → DefaultMaxDeliver (see EffectiveMaxDeliver)
	SpanName       string        // per-message consumer span name (e.g. "repolifecycle.consume")
	Name           string        // short consumer name, used as the log prefix

	// Tracer opens the per-message consumer span; nil uses the global OTel
	// tracer provider.
	Tracer trace.Tracer
	// Logger receives the scaffold's own log lines (decode-term warnings,
	// consume errors); nil uses slog.Default.
	Logger *slog.Logger

	// KeepInProgress runs a natsmsg.KeepInProgress heartbeat while handle
	// executes, for handlers that legitimately outrun AckWait. The extension
	// is capped, so a wedged handler still redelivers — see
	// natsmsg.KeepInProgress. The heartbeat stops when handle returns; a tick
	// racing the handler's own terminal Ack/Nak/Term is a client-side no-op
	// (nats.go marks the message disposed locally) that halts the heartbeat.
	//
	// Setting this forces the prefetch to one message (see MaxMessages): the
	// heartbeat extends only the delivery the handler holds, so anything
	// buffered behind a long handler would exhaust its AckWait unextended.
	KeepInProgress bool

	// MaxMessages caps how many deliveries the consume loop buffers
	// client-side (jetstream.PullMaxMessages); 0 uses the nats.go default
	// (500). AckWait runs from server delivery into that buffer, not from
	// callback dispatch, and callbacks run serially — so a consumer whose
	// handler can approach AckWait should keep this small or queued
	// deliveries expire and redeliver concurrently to other replicas.
	// KeepInProgress forces it to 1; setting both to conflicting values is a
	// Start error.
	MaxMessages int
}

// EffectiveAckWait is the AckWait actually applied to the JetStream consumer:
// Config.AckWait, or DefaultAckWait when zero. Use it — not the raw field —
// anywhere the real value matters, e.g. wiring a natsmsg.KeepInProgress
// heartbeat by hand (a zero ackWait there is a no-op).
func (c Config) EffectiveAckWait() time.Duration {
	if c.AckWait == 0 {
		return DefaultAckWait
	}
	return c.AckWait
}

// EffectiveMaxDeliver is the MaxDeliver actually applied to the JetStream
// consumer: Config.MaxDeliver, or DefaultMaxDeliver when zero. Use it — not
// the raw field — when building a backoff.Policy for this consumer's
// messages: the two packages read zero differently (here it means "default
// to DefaultMaxDeliver"; on the policy it means unlimited redeliveries, the
// jetstream.ConsumerConfig semantics), so passing a zero Config.MaxDeliver
// through verbatim would make TermOnExhaustion never fire on the broker's
// real final delivery and orphan work-queue messages (COR-762).
func (c Config) EffectiveMaxDeliver() int {
	if c.MaxDeliver == 0 {
		return DefaultMaxDeliver
	}
	return c.MaxDeliver
}

func (c Config) tracer() trace.Tracer {
	if c.Tracer == nil {
		return otel.Tracer("github.com/entireio/go-nuts/jsconsumer")
	}
	return c.Tracer
}

func (c Config) logger() *slog.Logger {
	if c.Logger == nil {
		return slog.Default()
	}
	return c.Logger
}

// isShutdownConsumeErr reports whether a consume error is the benign result
// of the connection going away during shutdown. [nuts.IsShutdownFetchErr]
// covers the core nats.go sentinels, but the jetstream consume loop surfaces
// its OWN [jetstream.ErrConnectionClosed] — a distinct value that wraps
// neither — so it must be matched separately or a clean rollout drain still
// logs a warning (the COR-923 noise this suppression exists to remove). As
// with the root classifier, it is only "clean" when ctx is already done; a
// mid-run connection loss is a genuine fault worth logging.
func isShutdownConsumeErr(ctx context.Context, err error) bool {
	return nuts.IsShutdownFetchErr(ctx, err) ||
		(ctx.Err() != nil && errors.Is(err, jetstream.ErrConnectionClosed))
}

// Runner is a live consume loop. Stop halts it and is idempotent.
type Runner struct {
	cc jetstream.ConsumeContext
	// closed is cc.Closed(), captured while the subscription is live (the
	// same channel is returned on every call, so capturing once avoids any
	// post-Stop race) — it closes when the consume loop has fully wound
	// down, including an in-flight handler.
	closed <-chan struct{}
	stop   sync.Once
}

// Stop halts the consume loop and blocks until it has fully wound down —
// including an in-flight handler — so a caller may tear down what handlers
// use (stores, publishers, the NATS connection) the moment it returns: the
// cancel → join → drain shutdown ordering (COR-923). Safe on a nil or
// never-Started Runner, idempotent, and safe for concurrent use — an
// explicit Stop can race the context-cancel stop armed by Start. Must not be
// called from inside the handler; it would deadlock waiting on itself.
func (r *Runner) Stop() {
	if r == nil || r.cc == nil {
		return
	}
	r.stop.Do(r.cc.Stop)
	<-r.closed
}

// Start creates/updates the durable consumer on nc and begins delivering
// messages to onMsg, returning a Runner that Stops when ctx is cancelled. The
// stream must already exist (provisioned declaratively); callers whose cells
// opt in per-stream gate Start behind that opt-in so a cell without the stream
// doesn't error at CreateOrUpdateConsumer.
//
// Consume errors are logged at Warn, except a drain/close during shutdown —
// both the core nats.go sentinels ([nuts.IsShutdownFetchErr]) and jetstream's
// own connection-closed error — which is a clean exit rather than a fault.
func Start(ctx context.Context, nc *nats.Conn, cfg Config, onMsg func(jetstream.Msg)) (*Runner, error) {
	if cfg.KeepInProgress && cfg.MaxMessages > 1 {
		return nil, fmt.Errorf("jsconsumer(%s): KeepInProgress requires MaxMessages <= 1: the heartbeat extends only the in-flight delivery, so %d buffered messages would exhaust AckWait behind a long handler", cfg.Name, cfg.MaxMessages)
	}
	if cfg.Durable == "" {
		// CreateOrUpdateConsumer accepts an empty durable and silently makes
		// an ephemeral, server-named consumer — losing the stable
		// resume-across-restarts behavior this scaffold promises.
		return nil, fmt.Errorf("jsconsumer(%s): Durable is required", cfg.Name)
	}
	if nc == nil {
		return nil, fmt.Errorf("jsconsumer(%s): nil nats conn", cfg.Name)
	}
	js, err := jetstream.New(nc)
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): jetstream.New: %w", cfg.Name, err)
	}
	cons, err := js.CreateOrUpdateConsumer(ctx, cfg.Stream, jetstream.ConsumerConfig{
		Durable:        cfg.Durable,
		AckPolicy:      jetstream.AckExplicitPolicy,
		AckWait:        cfg.EffectiveAckWait(),
		MaxDeliver:     cfg.EffectiveMaxDeliver(),
		FilterSubject:  cfg.FilterSubject,
		FilterSubjects: cfg.FilterSubjects,
	})
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): create consumer %s/%s: %w", cfg.Name, cfg.Stream, cfg.Durable, err)
	}
	consumeOpts := []jetstream.PullConsumeOpt{jetstream.ConsumeErrHandler(func(_ jetstream.ConsumeContext, cerr error) {
		if isShutdownConsumeErr(ctx, cerr) {
			return
		}
		cfg.logger().WarnContext(ctx, cfg.Name+": consume error", slog.Any("error", cerr))
	})}
	switch {
	case cfg.KeepInProgress:
		consumeOpts = append(consumeOpts, jetstream.PullMaxMessages(1))
	case cfg.MaxMessages > 0:
		consumeOpts = append(consumeOpts, jetstream.PullMaxMessages(cfg.MaxMessages))
	}
	cc, err := cons.Consume(onMsg, consumeOpts...)
	if err != nil {
		return nil, fmt.Errorf("jsconsumer(%s): consume %s: %w", cfg.Name, cfg.Stream, err)
	}
	r := &Runner{cc: cc, closed: cc.Closed()}
	go func() {
		<-ctx.Done()
		r.Stop()
	}()
	return r, nil
}

// Process runs the per-message prologue shared by every consumer: open the
// consumer span (re-parented to the producer across the NATS hop), decode the
// payload, and on a decode error record it, log "<Name>: decode <Stream>;
// term", invoke onUndecodable (so the caller bumps its own drop metric with
// its own attributes), and Term the message — a poison payload won't decode on
// redelivery. On success it invokes handle with the span-enriched context, the
// live span (for RecordError/SetStatus on the business error paths), the
// message, and the decoded event; with Config.KeepInProgress set, an AckWait
// heartbeat runs for the duration of handle.
//
// Callers wire Process as the func they pass to Start AND the entry point
// their tests drive, so the decode-or-term path is exercised the same way in
// production and tests.
func Process[E any](
	ctx context.Context,
	msg jetstream.Msg,
	cfg Config,
	decode func([]byte) (E, error),
	handle func(ctx context.Context, span trace.Span, msg jetstream.Msg, ev E),
	onUndecodable func(ctx context.Context),
) {
	ctx, span := natsmsg.StartConsumerSpan(ctx, cfg.tracer(), msg, cfg.SpanName)
	defer span.End()

	ev, err := decode(msg.Data())
	if err != nil {
		span.RecordError(err)
		span.SetStatus(codes.Error, "decode")
		cfg.logger().WarnContext(ctx, cfg.Name+": decode "+cfg.Stream+"; term",
			slog.Any("error", err), slog.String("subject", msg.Subject()))
		if onUndecodable != nil {
			onUndecodable(ctx)
		}
		if termErr := msg.Term(); termErr != nil {
			cfg.logger().WarnContext(ctx, cfg.Name+": term failed", slog.Any("error", termErr))
		}
		return
	}
	if cfg.KeepInProgress {
		stop := natsmsg.KeepInProgress(msg.InProgress, cfg.EffectiveAckWait())
		defer stop()
	}
	handle(ctx, span, msg, ev)
}

// Package backoff is the redelivery policy for transiently-failed JetStream
// deliveries: a flat NakWithDelay envelope bounded by MaxDeliver, with an
// optional Term on the final delivery.
//
// The Term-on-exhaustion posture is the COR-762 fix, lifted from
// mirror-pipeline's fanoutengine: on the final delivery a Nak is dropped
// silently by the broker (MaxDeliver reached), and on a WorkQueue stream the
// un-acked message then orphans — pinning the oldest-pending-age gauge — until
// StreamMaxAge finally expires it. Terming instead removes it cleanly. Streams
// where lingering is acceptable (a webhook stream whose max_age doubles as the
// retry backstop) leave TermOnExhaustion off and keep the plain Nak.
//
// The policy owns disposition only. Dead-letter capture stays with the caller,
// which should capture BEFORE disposing — gate it on [IsFinalDelivery]:
//
//	if backoff.IsFinalDelivery(msg, p.MaxDeliver) {
//		captureToDLQ(ctx, msg)
//	}
//	outcome, err := p.NakOrTerm(msg)
package backoff

import (
	"fmt"
	"time"

	"github.com/nats-io/nats.go/jetstream"
)

// Outcome is the disposition NakOrTerm chose, for the caller's metrics and
// logs.
type Outcome string

const (
	OutcomeNak  Outcome = "nak"
	OutcomeTerm Outcome = "term"
)

// Policy is the flat redelivery envelope a consumer applies to transient
// failures. MaxDeliver must match the consumer's on-server MaxDeliver — the
// policy detects the final delivery by comparing against it.
type Policy struct {
	// NakDelay is the flat delay before redelivery. Flat, not growing: the
	// envelope only rides out transient failures; MaxDeliver bounds the total.
	NakDelay time.Duration
	// MaxDeliver is the consumer's redelivery cap
	// (jetstream.ConsumerConfig.MaxDeliver). Non-positive means unlimited
	// redeliveries — matching the jetstream field's semantics — so no
	// delivery is ever final and NakOrTerm always Naks.
	MaxDeliver int
	// TermOnExhaustion makes the final delivery Term instead of Nak, so a
	// work-queue message is removed cleanly rather than orphaning un-acked
	// (COR-762). Callers with a DLQ capture before calling NakOrTerm.
	TermOnExhaustion bool
}

// NakOrTerm applies the policy to a transiently-failed delivery: NakWithDelay
// for redelivery, or — on the final delivery with TermOnExhaustion set — Term.
// Without TermOnExhaustion the final delivery still Naks; the broker drops the
// Nak at MaxDeliver and the stream's retention decides the message's fate.
//
// The returned Outcome reports which disposition was chosen, for the caller's
// metrics and logs. A disposition error is worth a log line but nothing more:
// a failed Nak redelivers via AckWait expiry anyway, and a failed Term on a
// work-queue stream means the message lingers exactly as it would have without
// the policy.
func (p Policy) NakOrTerm(msg jetstream.Msg) (Outcome, error) {
	if p.TermOnExhaustion && IsFinalDelivery(msg, p.MaxDeliver) {
		if err := msg.Term(); err != nil {
			return OutcomeTerm, fmt.Errorf("term on final delivery: %w", err)
		}
		return OutcomeTerm, nil
	}
	if err := msg.NakWithDelay(p.NakDelay); err != nil {
		return OutcomeNak, fmt.Errorf("nak with delay: %w", err)
	}
	return OutcomeNak, nil
}

// NumDelivered reports the JetStream delivery count (1 on first delivery), or
// 0 if metadata is unavailable (e.g. a synthetic test message).
func NumDelivered(msg jetstream.Msg) int {
	if meta, err := msg.Metadata(); err == nil {
		return int(meta.NumDelivered)
	}
	return 0
}

// IsFinalDelivery reports whether this is the last delivery before JetStream
// stops redelivering (NumDelivered has reached MaxDeliver), so a transient
// failure here is terminal rather than another Nak-and-retry. A non-positive
// maxDeliver means unlimited redeliveries (the jetstream.ConsumerConfig
// semantics), so no delivery is final — without the guard the zero value
// would read every delivery as final and Term on the first failure.
// Unavailable metadata also reads as non-final: the safe default is another
// retry, not a Term.
func IsFinalDelivery(msg jetstream.Msg, maxDeliver int) bool {
	if maxDeliver <= 0 {
		return false
	}
	if meta, err := msg.Metadata(); err == nil {
		return meta.NumDelivered >= uint64(maxDeliver)
	}
	return false
}

// Package natsmsg holds small JetStream message helpers shared by Entire's
// NATS consumers: W3C trace-context propagation over message headers (so a
// consumer span parents to the remote producer span and publish → consume
// stitches into one trace) and a KeepInProgress heartbeat for long-running
// handlers.
//
// It unifies two service-local copies — entire-core's internal/natsmsg and
// entire-api's internal/otelnats (itself ported from mirror-pipeline) — into
// the one shared implementation. Tracking: COR-929.
package natsmsg

import (
	"context"
	"math"

	"github.com/nats-io/nats.go"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/propagation"
	"go.opentelemetry.io/otel/trace"
)

// HeaderCarrier adapts nats.Header to the OTel TextMapCarrier contract so the
// configured propagator can inject/extract traceparent and baggage over a
// NATS hop.
type HeaderCarrier nats.Header

func (c HeaderCarrier) Get(key string) string {
	v := nats.Header(c).Values(key)
	if len(v) == 0 {
		return ""
	}
	return v[0]
}

func (c HeaderCarrier) Set(key, value string) { nats.Header(c).Set(key, value) }

// Values returns every value for key, satisfying [propagation.ValuesGetter]:
// without it the baggage propagator falls back to Get and reads only the
// first of multiple same-named headers, truncating multi-header W3C baggage.
func (c HeaderCarrier) Values(key string) []string { return nats.Header(c).Values(key) }

func (c HeaderCarrier) Keys() []string {
	keys := make([]string, 0, len(c))
	for k := range c {
		keys = append(keys, k)
	}
	return keys
}

var (
	_ propagation.TextMapCarrier = HeaderCarrier(nil)
	_ propagation.ValuesGetter   = HeaderCarrier(nil)
)

// Inject writes the propagator state from ctx into msg.Header, creating the
// header map if absent. Call before publishing so the consumer can re-parent.
func Inject(ctx context.Context, msg *nats.Msg) {
	if msg.Header == nil {
		msg.Header = nats.Header{}
	}
	otel.GetTextMapPropagator().Inject(ctx, HeaderCarrier(msg.Header))
}

// Extract returns ctx with propagator state from msg.Header applied. Call
// before starting the consumer span so it parents to the remote producer.
func Extract(ctx context.Context, msg *nats.Msg) context.Context {
	return ExtractHeader(ctx, msg.Header)
}

// ExtractHeader is Extract over a bare nats.Header — it takes the header map
// rather than the message so it serves both *nats.Msg (msg.Header) and
// jetstream.Msg (msg.Headers()).
func ExtractHeader(ctx context.Context, h nats.Header) context.Context {
	if h == nil {
		return ctx
	}
	return otel.GetTextMapPropagator().Extract(ctx, HeaderCarrier(h))
}

// Message is the subset of jetstream.Msg the consumer-span helper needs.
type Message interface {
	Headers() nats.Header
	Subject() string
}

// StartConsumerSpan extracts the propagated trace context from msg's headers
// and opens a consumer span named name on tr, pre-tagged with the standard
// messaging attributes (system=nats, destination=subject). Extra attrs are
// appended. Collapses the extract+start boilerplate shared by every JetStream
// consumer.
func StartConsumerSpan(ctx context.Context, tr trace.Tracer, msg Message, name string, attrs ...attribute.KeyValue) (context.Context, trace.Span) {
	ctx = ExtractHeader(ctx, msg.Headers())
	base := append([]attribute.KeyValue{
		attribute.String("messaging.system", "nats"),
		attribute.String("messaging.destination.name", msg.Subject()),
	}, attrs...)
	return tr.Start(ctx, name, trace.WithSpanKind(trace.SpanKindConsumer), trace.WithAttributes(base...)) //nolint:spancheck // the caller owns the span and Ends it
}

// ClampToInt64 narrows a JetStream sequence / delivery count (uint64 on the
// wire) to the int64 OTel attributes take, saturating instead of wrapping.
func ClampToInt64(v uint64) int64 {
	if v > math.MaxInt64 {
		return math.MaxInt64
	}
	return int64(v)
}

package natsmsg

import (
	"errors"
	"sync"
	"time"

	"github.com/nats-io/nats.go"
	"github.com/nats-io/nats.go/jetstream"
)

// keepInProgressMaxTicks caps the total AckWait extension at ~5×AckWait
// (ticks fire at AckWait/3). The heartbeat exists so a long handler that IS
// making progress — a whole-installation teardown fan-out, a multi-GB
// data-plane purge — doesn't get redelivered into a concurrent duplicate;
// it must NOT remove the broker's liveness failsafe entirely, or a wedged
// handler (hung I/O with no deadline) would pin its delivery to the wedged
// replica forever. Past the cap the extension stops and AckWait expiry
// redelivers to a healthy replica sharing the durable.
const keepInProgressMaxTicks = 15

// isPermanentInProgressErr reports whether an InProgress failure can never
// succeed on a later tick: the delivery was already terminally disposed (an
// Ack/Nak/Term racing the heartbeat) or carries no JetStream reply subject to
// extend. Both the jetstream and legacy *nats.Msg sentinel values are
// matched, since the callback may wrap either message type. Anything else —
// a reconnect-buffer overflow, a flush timeout — can recover once the
// connection does, so the heartbeat keeps trying until the tick cap.
func isPermanentInProgressErr(err error) bool {
	return errors.Is(err, jetstream.ErrMsgAlreadyAckd) ||
		errors.Is(err, jetstream.ErrMsgNoReply) ||
		errors.Is(err, nats.ErrMsgAlreadyAckd) ||
		errors.Is(err, nats.ErrMsgNoReply)
}

// KeepInProgress calls inProgress at ackWait/3 until stop is called, resetting
// the broker's redelivery timer while a long handler runs. The extension is
// capped (keepInProgressMaxTicks) — see the constant for why.
//
// inProgress wraps the message's InProgress call — func() error { return
// msg.InProgress() } — for either jetstream.Msg or the legacy *nats.Msg.
//
// A failing tick stops the heartbeat only when the failure is permanent
// (already disposed, no reply subject — see isPermanentInProgressErr);
// a transient failure such as a NATS blip keeps ticking, bounded by the
// cap, so one dropped extension during a reconnect doesn't silently
// forfeit the rest of the handler's runway and invite a concurrent
// redelivery mid-run.
//
// A non-positive interval (zero ackWait on a hand-built consumer; real
// consumer configs default it) returns a no-op stop.
//
// stop is idempotent and blocks until the ticker goroutine has exited, so
// no InProgress can race a terminal disposition (Ack/Nak/Term) issued
// after it returns.
func KeepInProgress(inProgress func() error, ackWait time.Duration) (stop func()) {
	interval := ackWait / 3
	if interval <= 0 {
		return func() {}
	}
	done := make(chan struct{})
	finished := make(chan struct{})
	go func() {
		defer close(finished)
		ticker := time.NewTicker(interval)
		defer ticker.Stop()
		for ticks := 0; ; {
			select {
			case <-done:
				return
			case <-ticker.C:
				ticks++
				if ticks > keepInProgressMaxTicks {
					return
				}
				if err := inProgress(); err != nil && isPermanentInProgressErr(err) {
					// A delivery that can't be extended won't start
					// succeeding on a later tick; stop instead of
					// spinning. The real failure surfaces on the
					// terminal Ack/Nak/Term.
					return
				}
			}
		}
	}()
	var once sync.Once
	return func() {
		once.Do(func() { close(done) })
		<-finished
	}
}

