1	package jsconsumer
2	
3	import (
4		"context"
5		"errors"
6		"strings"
7		"sync"
8		"sync/atomic"
9		"testing"
10		"time"
11	
12		natsserver "github.com/nats-io/nats-server/v2/server"
13		"github.com/nats-io/nats.go"
14		"github.com/nats-io/nats.go/jetstream"
15		"go.opentelemetry.io/otel/trace"
16	
17		"github.com/entireio/go-nuts/natsmsg/natsmsgtest"
18	)
19	
20	var testCfg = Config{Stream: "s_v1", Name: "testconsumer", SpanName: "test.consume"}
21	
22	// TestProcessDispatchesDecodedEvent: a payload that decodes reaches handle with the
23	// decoded event and a live span; the message is left for handle to ack/nak (Process
24	// does not touch it), and onUndecodable is not called.
25	func TestProcessDispatchesDecodedEvent(t *testing.T) {
26		msg := &natsmsgtest.FakeMsg{DataVal: []byte("payload")}
27		var (
28			gotEv   string
29			gotSpan trace.Span
30			gotMsg  jetstream.Msg
31			dropped bool
32		)
33		decode := func(b []byte) (string, error) { return "decoded:" + string(b), nil }
34		handle := func(_ context.Context, span trace.Span, m jetstream.Msg, ev string) {
35			gotEv, gotSpan, gotMsg = ev, span, m
36		}
37		Process(context.Background(), msg, testCfg, decode, handle, func(context.Context) { dropped = true })
38	
39		if gotEv != "decoded:payload" {
40			t.Errorf("handle got ev %q, want decoded:payload", gotEv)
41		}
42		if gotSpan == nil {
43			t.Error("handle got a nil span, want the live consumer span")
44		}
45		if gotMsg != msg {
46			t.Error("handle got a different msg than the one passed to Process")
47		}
48		if msg.Acked || msg.Termed || msg.Naks > 0 || len(msg.NakDelays) > 0 {
49			t.Error("Process disposed the message, want none (handle owns ack/nak)")
50		}
51		if dropped {
52			t.Error("onUndecodable called on a successful decode")
53		}
54	}
55	
56	// TestProcessTermsUndecodable: a decode error terms the message, bumps the caller's
57	// drop metric via onUndecodable, and never calls handle — a poison payload won't
58	// decode on redelivery.
59	func TestProcessTermsUndecodable(t *testing.T) {
60		msg := &natsmsgtest.FakeMsg{DataVal: []byte("garbage")}
61		handled := false
62		dropped := false
63		decode := func([]byte) (string, error) { return "", errors.New("bad payload") }
64		handle := func(context.Context, trace.Span, jetstream.Msg, string) { handled = true }
65		Process(context.Background(), msg, testCfg, decode, handle, func(context.Context) { dropped = true })
66	
67		if !msg.Termed {
68			t.Error("message not termed on a decode error")
69		}
70		if !dropped {
71			t.Error("onUndecodable not called on a decode error")
72		}
73		if handled {
74			t.Error("handle called despite a decode error")
75		}
76	}
77	
78	// TestProcessNilOnUndecodable: a nil onUndecodable is tolerated (still terms).
79	func TestProcessNilOnUndecodable(t *testing.T) {
80		msg := &natsmsgtest.FakeMsg{DataVal: []byte("garbage")}
81		decode := func([]byte) (string, error) { return "", errors.New("bad") }
82		Process(context.Background(), msg, testCfg, decode,
83			func(context.Context, trace.Span, jetstream.Msg, string) {}, nil)
84		if !msg.Termed {
85			t.Error("message not termed")
86		}
87	}
88	
89	// TestProcessKeepInProgress: with Config.KeepInProgress set, a handler that
90	// outruns AckWait/3 gets InProgress heartbeats, and the heartbeat goroutine has
91	// stopped by the time Process returns (no further ticks accrue).
92	func TestProcessKeepInProgress(t *testing.T) {
93		cfg := testCfg
94		cfg.KeepInProgress = true
95		cfg.AckWait = 30 * time.Millisecond // ticks at 10ms
96	
97		msg := &natsmsgtest.FakeMsg{DataVal: []byte("payload")}
98		decode := func(b []byte) (string, error) { return string(b), nil }
99		handle := func(context.Context, trace.Span, jetstream.Msg, string) {
100			time.Sleep(35 * time.Millisecond) // spans at least three ticks
101		}
102		Process(context.Background(), msg, cfg, decode, handle, nil)
103	
104		after := msg.InProgressN
105		if after == 0 {
106			t.Fatal("no InProgress heartbeat during a long handler")
107		}
108		time.Sleep(25 * time.Millisecond)
109		if msg.InProgressN != after {
110			t.Errorf("heartbeat still ticking after Process returned: %d → %d", after, msg.InProgressN)
111		}
112	}
113	
114	// TestProcessNoKeepInProgressByDefault: without the opt-in, a long handler gets
115	// no heartbeat — the broker's AckWait failsafe stays untouched.
116	func TestProcessNoKeepInProgressByDefault(t *testing.T) {
117		cfg := testCfg
118		cfg.AckWait = 30 * time.Millisecond
119	
120		msg := &natsmsgtest.FakeMsg{DataVal: []byte("payload")}
121		decode := func(b []byte) (string, error) { return string(b), nil }
122		handle := func(context.Context, trace.Span, jetstream.Msg, string) {
123			time.Sleep(35 * time.Millisecond)
124		}
125		Process(context.Background(), msg, cfg, decode, handle, nil)
126	
127		if msg.InProgressN != 0 {
128			t.Errorf("InProgress called %d times without KeepInProgress opt-in", msg.InProgressN)
129		}
130	}
131	
132	// TestConfigEffectiveValues pins the zero-value resolution callers must use
133	// when the real tunables matter outside the scaffold — most importantly
134	// feeding EffectiveMaxDeliver (never the raw field) into a backoff.Policy,
135	// where a zero means unlimited redeliveries instead of "default to 8".
136	func TestConfigEffectiveValues(t *testing.T) {
137		var zero Config
138		if got := zero.EffectiveAckWait(); got != DefaultAckWait {
139			t.Errorf("zero EffectiveAckWait = %v, want DefaultAckWait (%v)", got, DefaultAckWait)
140		}
141		if got := zero.EffectiveMaxDeliver(); got != DefaultMaxDeliver {
142			t.Errorf("zero EffectiveMaxDeliver = %d, want DefaultMaxDeliver (%d)", got, DefaultMaxDeliver)
143		}
