43	func TestTLSConfigFromFilesAndRotation(t *testing.T) {
44		dir := t.TempDir()
45		certFile := filepath.Join(dir, "tls.crt")
46		keyFile := filepath.Join(dir, "tls.key")
47		caFile := filepath.Join(dir, "ca.crt")
48	
49		firstCertPEM := writeSelfSignedCert(t, certFile, keyFile)
50		// Use the leaf as its own CA so the pool parses.
51		if err := os.WriteFile(caFile, firstCertPEM, 0o600); err != nil {
52			t.Fatal(err)
53		}
54	
55		cfg, err := TLSConfigFromFiles(certFile, keyFile, caFile)
56		if err != nil {
57			t.Fatalf("TLSConfigFromFiles: %v", err)
58		}
59		if cfg.MinVersion != tls.VersionTLS13 {
60			t.Errorf("MinVersion = %x, want TLS 1.3", cfg.MinVersion)
61		}
62	
63		got1, err := cfg.GetClientCertificate(&tls.CertificateRequestInfo{})
64		if err != nil {
65			t.Fatalf("GetClientCertificate: %v", err)
66		}
67	
68		// Rotate the cert+key on disk. The callback must serve the NEW cert on the
69		// next handshake without the config being rebuilt.
70		writeSelfSignedCert(t, certFile, keyFile)
71		got2, err := cfg.GetClientCertificate(&tls.CertificateRequestInfo{})
72		if err != nil {
73			t.Fatalf("GetClientCertificate after rotation: %v", err)
74		}
75		if bytes.Equal(got1.Certificate[0], got2.Certificate[0]) {
76			t.Fatal("GetClientCertificate did not pick up the rotated cert")
77		}
78	}
79	
80	// writeSelfSignedCert generates a fresh self-signed cert (random serial + key)
81	// and writes it as PEM to certFile/keyFile, returning the certificate PEM. Each
82	// call produces a distinct certificate, so calling it twice simulates rotation.
83	func writeSelfSignedCert(t *testing.T, certFile, keyFile string) []byte {
84		t.Helper()
85		priv, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
86		if err != nil {
87			t.Fatal(err)
88		}
89		tmpl := &x509.Certificate{
90			SerialNumber:          randSerial(t),
91			Subject:               pkix.Name{CommonName: "nuts-test"},
92			NotBefore:             time.Now().Add(-time.Hour),
93			NotAfter:              time.Now().Add(time.Hour),
94			KeyUsage:              x509.KeyUsageDigitalSignature | x509.KeyUsageCertSign,
95			IsCA:                  true,
96			BasicConstraintsValid: true,
97		}
98		der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &priv.PublicKey, priv)
99		if err != nil {
100			t.Fatal(err)
101		}
102		certPEM := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der})
103		keyDER, err := x509.MarshalPKCS8PrivateKey(priv)
104		if err != nil {
105			t.Fatal(err)
106		}
107		keyPEM := pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: keyDER})
108		if err := os.WriteFile(certFile, certPEM, 0o600); err != nil {
109			t.Fatal(err)
110		}
111		if err := os.WriteFile(keyFile, keyPEM, 0o600); err != nil {
112			t.Fatal(err)
113		}
114		return certPEM
115	}
