118		// The default posture is fail-fast: an unreachable server must yield an
119		// error, not a silently-reconnecting connection reported as healthy.
120		if _, err := Connect(t.Context(), "nats://127.0.0.1:1", WithoutTLS()); err == nil {
121			t.Fatal("expected an error connecting to an unreachable server without retry-on-failed-connect")
122		}
