126		// Opting in keeps the initial failure non-fatal: a connection is returned in
127		// a not-yet-connected state and retries in the background.
128		nc, err := Connect(t.Context(), "nats://127.0.0.1:1", WithoutTLS(), WithRetryOnFailedConnect())
129		if err != nil {
130			t.Fatalf("retry-on-failed-connect should not error on initial failure: %v", err)
131		}
132		if nc == nil {
133			t.Fatal("expected a non-nil connection in retry-on-failed-connect mode")
134		}
135		t.Cleanup(nc.Close)
136		if nc.IsConnected() {
137			t.Fatal("did not expect an established connection to an unreachable server")
138		}
139	}
