142		var buf bytes.Buffer
143		logger := slog.New(slog.NewTextHandler(&buf, nil))
144	
145		nc, err := Connect(t.Context(), runEmbeddedServer(t), WithoutTLS(), WithName("worker"), WithLogger(logger))
