156	// TestTLSConfigCARotation guards that the trusted CA is re-read from disk on
157	// every handshake (via VerifyConnection) rather than pinned once at startup, so
158	// a CA rotation is honored without a process restart.
159	func TestTLSConfigCARotation(t *testing.T) {
160		dir := t.TempDir()
161		certFile := filepath.Join(dir, "tls.crt")
162		keyFile := filepath.Join(dir, "tls.key")
163		caFile := filepath.Join(dir, "ca.crt")
164	
165		// A client identity keypair — GetClientCertificate just needs to load it.
166		writeSelfSignedCert(t, certFile, keyFile)
167	
168		caA := newTestCA(t)
169		caB := newTestCA(t)
170		serverLeaf := caA.signLeaf(t, "nats.internal") // signed by CA A only
171	
172		// Start out trusting CA A.
173		if err := os.WriteFile(caFile, caA.certPEM, 0o600); err != nil {
174			t.Fatal(err)
175		}
176		cfg, err := TLSConfigFromFiles(certFile, keyFile, caFile)
177		if err != nil {
178			t.Fatalf("TLSConfigFromFiles: %v", err)
179		}
180	
181		stateA := tls.ConnectionState{ServerName: "nats.internal", PeerCertificates: []*x509.Certificate{serverLeaf}}
182		if err := cfg.VerifyConnection(stateA); err != nil {
183			t.Fatalf("verify against the trusting CA should pass: %v", err)
184		}
185	
186		// Rotate the CA file to a different CA that did NOT sign the server leaf.
187		if err := os.WriteFile(caFile, caB.certPEM, 0o600); err != nil {
188			t.Fatal(err)
189		}
190		if err := cfg.VerifyConnection(stateA); err == nil {
191			t.Fatal("verify must fail after the CA on disk is rotated to one that did not sign the server cert")
192		}
193	
194		// And a leaf signed by the newly-trusted CA B must now verify.
195		stateB := tls.ConnectionState{ServerName: "nats.internal", PeerCertificates: []*x509.Certificate{caB.signLeaf(t, "nats.internal")}}
196		if err := cfg.VerifyConnection(stateB); err != nil {
197			t.Fatalf("verify against the rotated-in CA should pass: %v", err)
198		}
199	}
200	
201	// testCA is a self-signed certificate authority for tests.
202	type testCA struct {
203		cert    *x509.Certificate
204		key     *ecdsa.PrivateKey
205		certPEM []byte
206	}
207	
208	func newTestCA(t *testing.T) testCA {
209		t.Helper()
210		key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
211		if err != nil {
212			t.Fatal(err)
213		}
214		tmpl := &x509.Certificate{
215			SerialNumber:          randSerial(t),
216			Subject:               pkix.Name{CommonName: "nuts-test-ca"},
217			NotBefore:             time.Now().Add(-time.Hour),
218			NotAfter:              time.Now().Add(time.Hour),
219			KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageDigitalSignature,
220			IsCA:                  true,
221			BasicConstraintsValid: true,
222		}
223		der, err := x509.CreateCertificate(rand.Reader, tmpl, tmpl, &key.PublicKey, key)
224		if err != nil {
225			t.Fatal(err)
226		}
227		cert, err := x509.ParseCertificate(der)
228		if err != nil {
229			t.Fatal(err)
230		}
231		return testCA{cert: cert, key: key, certPEM: pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der})}
232	}
233	
234	// signLeaf returns a server leaf certificate with the given DNS SAN, signed by
235	// the CA.
236	func (ca testCA) signLeaf(t *testing.T, dnsName string) *x509.Certificate {
237		t.Helper()
238		key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
239		if err != nil {
240			t.Fatal(err)
241		}
242		tmpl := &x509.Certificate{
243			SerialNumber: randSerial(t),
244			Subject:      pkix.Name{CommonName: dnsName},
245			DNSNames:     []string{dnsName},
246			NotBefore:    time.Now().Add(-time.Hour),
247			NotAfter:     time.Now().Add(time.Hour),
248			KeyUsage:     x509.KeyUsageDigitalSignature,
249			ExtKeyUsage:  []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
250		}
251		der, err := x509.CreateCertificate(rand.Reader, tmpl, ca.cert, &key.PublicKey, ca.key)
252		if err != nil {
253			t.Fatal(err)
254		}
255		cert, err := x509.ParseCertificate(der)
256		if err != nil {
257			t.Fatal(err)
258		}
259		return cert
260	}
261	
262	func randSerial(t *testing.T) *big.Int {
263		t.Helper()
264		serial, err := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 128))
265		if err != nil {
266			t.Fatal(err)
267		}
268		return serial
269	}
