1	package backoff
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	
8		"github.com/nats-io/nats.go/jetstream"
9	
10		"github.com/entireio/go-nuts/natsmsg/natsmsgtest"
11	)
12	
13	const testDelay = 5 * time.Second
14	
15	func delivered(n uint64) *natsmsgtest.FakeMsg {
16		return &natsmsgtest.FakeMsg{Meta: &jetstream.MsgMetadata{NumDelivered: n}}
17	}
18	
19	// TestNakOrTermNaksBeforeExhaustion: a transient failure with deliveries left
20	// redelivers with the flat policy delay.
21	func TestNakOrTermNaksBeforeExhaustion(t *testing.T) {
22		p := Policy{NakDelay: testDelay, MaxDeliver: 5, TermOnExhaustion: true}
23		msg := delivered(4)
24	
25		got, err := p.NakOrTerm(msg)
26		if err != nil {
27			t.Fatalf("NakOrTerm: %v", err)
28		}
29		if got != OutcomeNak {
30			t.Errorf("outcome = %q, want nak", got)
31		}
32		if len(msg.NakDelays) != 1 || msg.NakDelays[0] != testDelay {
33			t.Errorf("NakDelays = %v, want one nak with the policy delay", msg.NakDelays)
34		}
35		if msg.Termed {
36			t.Error("termed before exhaustion")
37		}
38	}
39	
40	// TestNakOrTermTermsOnFinalDelivery pins the COR-762 fix: on the final delivery
41	// of a work-queue consumer (TermOnExhaustion), Term removes the message cleanly
42	// instead of a Nak the broker drops — which would orphan it un-acked until
43	// StreamMaxAge.
44	func TestNakOrTermTermsOnFinalDelivery(t *testing.T) {
45		p := Policy{NakDelay: testDelay, MaxDeliver: 5, TermOnExhaustion: true}
46		msg := delivered(5)
47	
48		got, err := p.NakOrTerm(msg)
49		if err != nil {
50			t.Fatalf("NakOrTerm: %v", err)
51		}
52		if got != OutcomeTerm {
53			t.Errorf("outcome = %q, want term", got)
54		}
55		if !msg.Termed {
56			t.Error("final delivery not termed")
57		}
58		if len(msg.NakDelays) != 0 {
59			t.Errorf("NakDelays = %v, want none on the term path", msg.NakDelays)
60		}
61	}
62	
63	// TestNakOrTermKeepsNakWithoutOptIn: without TermOnExhaustion the final
64	// delivery still Naks — streams whose max_age doubles as the retry backstop
65	// keep their existing posture.
66	func TestNakOrTermKeepsNakWithoutOptIn(t *testing.T) {
67		p := Policy{NakDelay: testDelay, MaxDeliver: 5}
68		msg := delivered(5)
69	
70		got, err := p.NakOrTerm(msg)
71		if err != nil {
72			t.Fatalf("NakOrTerm: %v", err)
73		}
74		if got != OutcomeNak {
75			t.Errorf("outcome = %q, want nak", got)
76		}
77		if msg.Termed {
78			t.Error("termed without the TermOnExhaustion opt-in")
79		}
80	}
81	
82	// TestNakOrTermMissingMetadataNaks: a message without JetStream metadata (a
83	// synthetic test message) reads as non-final — the safe default is another
84	// retry, never a Term.
85	func TestNakOrTermMissingMetadataNaks(t *testing.T) {
86		p := Policy{NakDelay: testDelay, MaxDeliver: 1, TermOnExhaustion: true}
87		msg := &natsmsgtest.FakeMsg{MetaErr: errors.New("no metadata")}
88	
89		got, err := p.NakOrTerm(msg)
90		if err != nil {
91			t.Fatalf("NakOrTerm: %v", err)
92		}
93		if got != OutcomeNak {
94			t.Errorf("outcome = %q, want nak", got)
95		}
96		if msg.Termed {
97			t.Error("termed a message whose delivery count is unknown")
98		}
99	}
100	
101	// TestNakOrTermZeroMaxDeliverNaks pins the zero-value guard: MaxDeliver left
102	// at 0 means unlimited redeliveries (the jetstream.ConsumerConfig semantics),
103	// so no delivery is final and a transient failure Naks — it must NOT read
104	// every delivery as final and Term on the first failure.
105	func TestNakOrTermZeroMaxDeliverNaks(t *testing.T) {
106		p := Policy{NakDelay: testDelay, TermOnExhaustion: true} // MaxDeliver unset
107		msg := delivered(1)
108	
109		got, err := p.NakOrTerm(msg)
110		if err != nil {
111			t.Fatalf("NakOrTerm: %v", err)
112		}
113		if got != OutcomeNak {
114			t.Errorf("outcome = %q, want nak", got)
115		}
116		if msg.Termed {
117			t.Error("termed on the first delivery with an unset MaxDeliver")
118		}
119	}
120	
121	func TestNumDelivered(t *testing.T) {
122		if got := NumDelivered(delivered(3)); got != 3 {
123			t.Errorf("NumDelivered = %d, want 3", got)
124		}
125		if got := NumDelivered(&natsmsgtest.FakeMsg{MetaErr: errors.New("none")}); got != 0 {
126			t.Errorf("NumDelivered without metadata = %d, want 0", got)
127		}
128	}
129	
130	func TestIsFinalDelivery(t *testing.T) {
131		if IsFinalDelivery(delivered(4), 5) {
132			t.Error("delivery 4/5 read as final")
